import unittest
import example

class TestNumberGuessingGame(unittest.TestCase):
    def test_generate_number(self):
        # Test that the generated number is between 1 and 10
        for _ in range(100):
            number = example.generate_number()
            self.assertTrue(1 <= number <= 10, f"Generated number {number} is out of range")

    def test_get_guess_valid_input(self):
        # Test valid input (integer between 1 and 10)
        with unittest.mock.patch('builtins.input', return_value='5'):
            self.assertEqual(example.get_guess(), 5)

    def test_get_guess_invalid_input(self):
        # Test invalid input (non-integer)
        with unittest.mock.patch('builtins.input', side_effect=['a', '12', '7']):
            self.assertEqual(example.get_guess(), 7)

    def test_check_guess_correct(self):
        # Test correct guess
        self.assertEqual(example.check_guess(5, 5), "You guessed it!")

    def test_check_guess_too_low(self):
